t.script:
document.addEventListener("DOMContentLoaded", function () {
  const input = document.getElementById("barcode_input");
  const status = document.getElementById("scan_status");

  window.triggerScan = function () {
    if (!input.value.trim()) return;
    const barcode = input.value.trim();
    status.style.display = "block";
    status.className = "alert alert-info text-center";
    status.innerText = "⏳ Đang xử lý mã: " + barcode;

    fetch("/custom_barcode_scan/ui/scan", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Requested-With": "XMLHttpRequest"
      },
      body: JSON.stringify({ barcode })
    })
    .then(res => res.json())
    .then(action => {
      if (action && action.type) {
        status.className = "alert alert-success text-center";
        status.innerText = "✅ Mở phiếu...";
        window.odoo.__DEBUG__.services["web.action_service"].doAction(action);
      } else {
        status.className = "alert alert-warning text-center";
        status.innerText = action.error || action.warning || "Không rõ phản hồi.";
      }
    })
    .catch(err => {
      status.className = "alert alert-danger text-center";
      status.innerText = "❌ Lỗi: " + err;
    });

    input.value = "";
  };

  input.addEventListener("keypress", function (e) {
    if (e.key === "Enter") {
      triggerScan();
    }
  });
});
